def make_palindrome(string: str) -> str:
    def is_palindrome(s: str) -> bool:
        return s == s[::-1]

    def longest_palindromic_postfix(s: str) -> int:
        for i in range(len(s), -1, -1):
            if is_palindrome(s[i:]):
                return i
        return 0

    n = len(string)
    length_of_palindrome_suffix = longest_palindromic_postfix(string)
    prefix_to_append = string[:length_of_palindrome_suffix]
    return string + prefix_to_append[::-1]

